cd /workspace/pr; for v in base head; do for n in 14 15; do echo "== $v pr-$n"; jq -r '.fix_regions[].file' $v/evals/fixtures/review-prs/manifests/pr-$n.json | python3 -I -c '
import sys
N={"checksums.json","REPO-MAP.md",".build-manifest.json"}
for l in sys.stdin:
    p=l.strip(); parts=p.split("/")
    if "dist" in parts[:-1] or parts[-1] in N or parts[-1].endswith((".map",".d.ts",".checksum")): print("GEN",p)
' | sort | uniq -c; jq '.defects|length, (.fix_regions|length)' $v/evals/fixtures/review-prs/manifests/pr-$n.json; jq -c 'del(.fix_regions)' $v/evals/fixtures/review-prs/manifests/pr-$n.json | sha256sum; done; done
